   SELECT *
	 FROM TB_QLT020
	WHERE 1 = 1
	  AND INSP_ITEM_GRP_CD = #{INSP_ITEM_GRP_CD}
	  AND MATNR = #{MATNR}
	  AND WERKS = #{WERKS}
	  AND MSRM_DATE = TO_DATE(#{MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
	  AND PRC_SEQNO = #{PRC_SEQNO}

UPDATE TB_QLT020 
   SET DOC_ID = #{DOC_ID}, CFRM_ID = #{SES_USER_ID}
 WHERE 1 = 1
   AND INSP_ITEM_GRP_CD = #{INSP_ITEM_GRP_CD}
   AND MATNR = #{MATNR}
   AND WERKS = #{WERKS}
   AND MSRM_DATE = TO_DATE(#{MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
   AND PRC_SEQNO = #{PRC_SEQNO}

UPDATE TB_QLT020 SET
APVR_STA = #{APVR_STA},CFRM_DATE=sysdate
WHERE DOC_ID = #{DOC_ID}

SELECT DOC_ID,NVL(APVR_STA, '0') APVR_STA
FROM TB_INV001
WHERE WERKS = #{WERKS}
  AND STOR_LOC_CD=#{STOR_LOC_CD}
  AND IND_BCD=#{IND_BCD}
  AND MATNR=#{MATNR}

